3 | /**
4 |  * The only public way to read or write settlements. Lookups check the hot
5 |  * partition first and then the archive, so archival never hides a settlement.
6 |  */
7 | 
8 | export function recordSettlement(orderId: string, amountCents: number, day: number): SettlementRow {
9 |   if (!Number.isInteger(amountCents) || amountCents <= 0) {
10 |     throw new Error(`Settlement amount must be a positive integer, got ${amountCents}`);
11 |   }
12 |   const row: SettlementRow = { orderId, amountCents, settledDay: day, debitCents: amountCents, creditCents: amountCents };
13 |   liveSettlements.set(orderId, row);
14 |   return row;
15 | }
16 | 
17 | export function getSettlement(orderId: string): SettlementRow | undefined {
18 |   return liveSettlements.get(orderId) ?? archivedSettlements.get(orderId);
19 | }
20 | 
21 | /** Move settlements that settled before `cutoffDay` to cold storage. Returns how many moved. */
22 | export function archiveSettledBefore(cutoffDay: number): number {
23 |   let moved = 0;
24 |   for (const [orderId, row] of liveSettlements) {
25 |     if (row.settledDay < cutoffDay) {
26 |       archivedSettlements.set(orderId, row);
27 |       liveSettlements.delete(orderId);
28 |       moved++;
29 |     }
30 |   }
31 |   return moved;
32 | }
